#include <stdio.h>
#include <limits.h>

int main(void) {
    int n;
    scanf("%d", &n);

    int dp[100001];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int x = i;
        int best = INT_MAX;

        while (x > 0) {
            int d = x % 10;
            x /= 10;

            if (d > 0) {
                int candidate = dp[i - d] + 1;
                if (candidate < best) {
                    best = candidate;
                }
            }
        }

        dp[i] = best;
    }

    printf("%d\n", dp[n]);
    return 0;
}
